import React from "react";

export default function App() {
  return (
    <>
      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
        }

        .home{
          position:relative;
          width:100%;
          height:100vh;
          overflow:hidden;
          background:black;
        }

        .bg-video{
          position:absolute;
          top:50%;
          left:50%;
          width:100%;
          height:100%;
          object-fit:cover;
          transform:translate(-50%, -50%);
          opacity:0.6;
        }

        .navbar{
          position:relative;
          z-index:10;
          width:100%;
          padding:20px 40px;
          color:white;
          font-size:22px;
          font-weight:bold;
        }

        .center-text{
          position:absolute;
          top:50%;
          left:50%;
          transform:translate(-50%,-50%);
          color:white;
          font-size:60px;
          font-weight:900;
          letter-spacing:3px;
          z-index:10;
          animation:popIn 1.3s ease forwards;
          opacity:0;
        }

        @keyframes popIn{
          0%{
            transform:translate(-50%,-50%) scale(0);
            opacity:0;
          }
          100%{
            transform:translate(-50%,-50%) scale(1);
            opacity:1;
          }
        }
      `}</style>

      <div className="home">
        <video className="bg-video" autoPlay loop muted playsInline>
          <source src="/vide.mp4" type="video/mp4" />
        </video>

        <nav className="navbar">
          <h2>My Website</h2>
        </nav>

        <div className="center-text">
          Oujda City
        </div>
      </div>
    </>
  );
}
